'use strict';
const fs=require('node:fs'),path=require('node:path');
const {admitInput,predict}=require('./dpiTechniqueActualQualification');
const {saveBounded}=require('./boundedJsonArtifact');
function directory(p){if(!path.isAbsolute(p)||fs.realpathSync(p)!==p)throw Error('PRIVATE_DIRECTORY');const s=fs.lstatSync(p);if(!s.isDirectory()||s.uid!==process.getuid()||(s.mode&0o777)!==0o700)throw Error('PRIVATE_DIRECTORY');return s;}
function admit(env){if(env.DPI_TECHNIQUE_PHASE_A_ACTUAL!=='1')throw Error('ACTUAL_GATE');const input=env.DPI_TECHNIQUE_PHASE_A_INPUT,root=env.DPI_TECHNIQUE_PHASE_A_OUTPUT_ROOT;if(typeof input!=='string'||!path.isAbsolute(input))throw Error('INPUT_PATH');const parent=directory(root);const fd=fs.openSync(input,fs.constants.O_RDONLY|fs.constants.O_NOFOLLOW);let bytes;try{const stat=fs.fstatSync(fd);if(!stat.isFile()||stat.size>100000)throw Error('INPUT_BOUND');const buffer=Buffer.alloc(100001);let n=0;while(n<buffer.length){const got=fs.readSync(fd,buffer,n,buffer.length-n,null);if(!got)break;n+=got;}bytes=buffer.subarray(0,n);admitInput(bytes);}finally{fs.closeSync(fd);}return {root,parent,bytes};}
async function run(env,{transportFactory,contractFactory,providerFactory,upstream,emit=()=>{},predictor=predict}={}){
 const admitted=admit(env),artifactDirectory=fs.mkdtempSync(path.join(admitted.root,'phase-a-'));fs.chmodSync(artifactDirectory,0o700);const owned=directory(artifactDirectory),resultPath=path.join(artifactDirectory,'result.json');const parentNow=directory(admitted.root);if(parentNow.ino!==admitted.parent.ino||parentNow.dev!==admitted.parent.dev)throw Error('DIRECTORY_REPLACED');const parentFd=fs.openSync(admitted.root,'r');try{fs.fsyncSync(parentFd);}finally{fs.closeSync(parentFd);}
 const state={version:'dpi-technique-phase-a-composition-v1',status:'preparing',technicalComplete:false,semanticAccepted:null,credit:false,genuineActor:false,prediction:null,records:[],wire:null,cleanup:{complete:false},failure:null};
 function save(){const parent=directory(admitted.root),current=directory(artifactDirectory);if(parent.ino!==admitted.parent.ino||parent.dev!==admitted.parent.dev||current.ino!==owned.ino||current.dev!==owned.dev)throw Error('DIRECTORY_REPLACED');for(const name of ['result.json','result.json.tmp']){const p=path.join(artifactDirectory,name);if(fs.existsSync(p)){const s=fs.lstatSync(p);if(!s.isFile()||s.nlink!==1||s.uid!==process.getuid()||(s.mode&0o777)!==0o600)throw Error('ARTIFACT_OWNERSHIP');}}saveBounded(resultPath,state);const fd=fs.openSync(artifactDirectory,'r');try{fs.fsyncSync(fd);}finally{fs.closeSync(fd);}}
 emit({type:'artifact',artifactDirectory,resultPath});save();let transport,active=null,token=null;
 try{
  if(!transportFactory||!contractFactory||!providerFactory||typeof upstream!=='function')throw Error('DEPENDENCIES_REQUIRED');
  const contract=contractFactory({model:'llama3.1:8b'});
  transport=transportFactory({phase:'A',fetch:async(url,options={})=>{const u=new URL(url);if(u.pathname==='/api/chat'){const pending=token;token=null;contract.validate(pending,{caseId:active,method:options.method,path:u.pathname,body:options.body});}else if(u.pathname!=='/api/tags')throw Error('TRANSPORT_PATH');return upstream(url,options);},record:wire=>{state.wire=wire;save();}});
  await transport.initialize();const {judgeUrl}=await transport.listen();const provider=providerFactory({provider:'ollama',model:'llama3.1:8b',baseURL:judgeUrl});
  state.prediction=await predictor({inputBytes:admitted.bytes,model:{chat:async(messages,tools,options)=>{token=contract.expect({caseId:active,kind:'judge',messages,tools,options});const result=await provider.chat(messages,tools,options);if(token!==null)throw Error('REQUEST_NOT_DISPATCHED');return result;}},onCaseStart:id=>{active=id;contract.beginCase(id);transport.beginCase(id);},onCaseEnd:()=>{transport.endCase();contract.endCase();active=null;},onRecord:record=>{state.records.push(record);save();}});
  state.technicalComplete=state.prediction.status==='predictions-complete-semantic-review-pending'&&!state.prediction.physicalPending;state.status=state.technicalComplete?'predictions-complete-semantic-review-pending':'incomplete';
 }catch{state.failure='COMPOSITION_OR_TRANSPORT_FAILURE';state.status='incomplete';state.technicalComplete=false;}
 finally{if(transport){try{await transport.close();state.cleanup.complete=true;}catch{state.cleanup.failure='PHYSICAL_CLOSE_UNVERIFIED';state.technicalComplete=false;state.status='incomplete';}state.wire=transport.snapshot();}else state.cleanup.complete=true;save();emit({type:'status',status:state.status,technicalComplete:state.technicalComplete,cleanupComplete:state.cleanup.complete});}
 return {artifactDirectory,resultPath,state};
}
async function main(){admit(process.env);const {createTechniqueTransport}=require('./dpiTechniqueActualTransport');const {createRequestContract}=require('./dpiTechniqueRequestContractV2');const {createLangChainProvider}=require('../../server/agent-runtime/providers/langchainProvider');const result=await run(process.env,{transportFactory:createTechniqueTransport,contractFactory:createRequestContract,providerFactory:createLangChainProvider,upstream:global.fetch,emit:value=>process.stdout.write(JSON.stringify(value)+'\n')});if(!result.state.technicalComplete)process.exitCode=1;}
module.exports={admit,run};
if(require.main===module)main().catch(()=>{process.stderr.write('Phase A unavailable\n');process.exitCode=1;});
